export const journeySteps=[['确认位置','Locate'],['前往建筑','Building'],['找到楼层','Floor'],['室内线索','Inside'],['确认找到','Confirm']];
export function journeyNext(stage,event){const routes={0:{located:1},1:{entered:2},2:{floorReached:3},3:{atDoor:4},4:{retry:3}};return routes[stage]?.[event]??stage;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function journeyMarkup({p,b,stage,en,origin,floor,stepFree,recovery,reminders,muted,estimate}){
 const t=(zh,eng)=>en?eng:zh,n=o=>en?o.name:o.zh,button=(id,zh,eng,cls='primary full')=>`<button id="${id}" class="${cls}">${t(zh,eng)}</button>`,sign=p.type==='toilet'?t('厕所标识','TOILETS'):p.name.split('·').at(-1).trim(),via=stepFree?t('电梯','lift'):t('楼梯','stairs');
 const note=`<p class="journey-demo">${t('情境演示 · 假设定位与室内导航服务可用；以下入口、参照点和路线未经现场核验。','SCENARIO · Assumes location and indoor routing. Entrances, landmarks and routes below are not field-verified.')}</p>`;
 const facts=`<div class="journey-destination"><small>${esc(b.id+' / '+n(b))}</small><strong>${esc(n(p))}</strong><span>${esc(floor)}</span></div>`;
 let body='';
 if(stage===0)body=`<h3>${t('先确认，线索从哪里开始。','First, place the starting pin.')}</h3><div class="location-fix"><span class="location-pulse" aria-hidden="true"></span><div><small>${t('模拟定位 · 校园内','SIMULATED CAMPUS FIX')}</small><strong>${esc(n(origin))}</strong><span>${t('假设已获授权；未读取设备 GPS','Permission assumed; device GPS is not read')}</span></div></div><p>${t('先核对起点，再规划到建筑、楼层和门口的整段路径。定位不符时可以更换参考位置。','Check the starting point before following the building, floor and door clues. Change the reference point if it does not match.')}</p>${button('locateScenario','模拟获取校园位置','Use simulated campus location','outline full')}${button('changeJourneyOrigin','更换参考位置','Change reference position','text-button full')}<label class="reminder-choice"><input id="journeyReminder" type="checkbox" ${reminders?'checked':''}>${t('允许本次演示的到楼提示','Allow approach prompts for this demo')}</label>${button('confirmOrigin','确认起点，开始找路','Confirm origin. Start the trail')}`;
 if(stage===1)body=`<h3>${t('沿校园线索，先到这栋楼。','Follow the campus clue to the building.')}</h3><div class="route-ticket"><span>${esc(n(origin))}</span><span>↓</span><strong>${esc(b.id+' · '+n(b))}</strong><small>${esc(estimate)} · ${t('示例预计','scenario estimate')}</small></div><ol class="checkpoint-list"><li>${t('按校园地图朝目标建筑前进。','Follow the campus map towards the destination building.')}</li><li>${t('示例参照：建筑主入口处的名称牌。','Scenario landmark: the name sign at the main entrance.')}</li><li>${t('核对建筑名，再确认已进入入口大厅。','Match the building name, then confirm entry to the foyer.')}</li></ol>${button('enterBuilding','已到入口并进入建筑（演示）','At the entrance. Enter building (demo)')}<div class="guide-controls">${button('replayPrompt','播放到楼提示','Play approach prompt','text-button')}${button('muteGuide',muted?'恢复提醒':'暂停提醒',muted?'Resume prompts':'Pause prompts','text-button')}</div>`;
 if(stage===2)body=`<h3>${t('进楼后，先找楼层指示。','Inside, find the floor sign first.')}</h3><div class="floor-ticket compact"><span>${t('目标楼层 · 情境信息','DESTINATION FLOOR · SCENARIO')}</span><strong>${esc(floor)}</strong></div><ol class="checkpoint-list"><li>${t('示例参照：入口大厅里的楼层索引牌。','Scenario landmark: the floor directory in the entrance foyer.')}</li><li>${t('对照目的地所在楼层，寻找电梯或楼梯标识。','Match the destination floor, then look for lift or stairs signs.')}</li><li>${t('到层后核对平台或电梯出口处的楼层牌；目的地与入口同层时无需上下楼。','At the landing, check the floor label beside the stairs or lift exit. Stay on the entry floor if it matches the destination.')}</li></ol><label class="step-free-choice"><input id="stepFree" type="checkbox" ${stepFree?'checked':''}>${t('优先电梯与无台阶路径（演示）','Prefer lift and step-free path (demo)')}</label>${button('atFloor','已核对楼层，继续找门口','Floor checked. Find the door')}`;
 if(stage===3)body=`<h3>${t('沿室内线索，找到具体门口。','Follow the indoor clues to the door.')}</h3><div class="sign-clue"><small>${t('下一块要核对的标识 · 示例','NEXT SIGN TO MATCH · SCENARIO')}</small><strong>↱ ${esc(sign)}</strong><span>${esc(floor)}</span></div><ol class="checkpoint-list"><li>${t('从本层的','From the ')}${esc(via)}${t('出口进入走廊。',' exit, enter the corridor on this floor.')}</li><li>${t('示例路线：沿走廊直行，在转角查看方向牌，向右进入目标区域。','Scenario route: follow the corridor, check the direction sign at the corner, then turn right into the destination area.')}</li><li>${p.type==='toilet'?t('在目标区域查找厕所图标，并核对所需设施标识。','Look for the toilet icon and check the required facility symbols.'):t('查看门边或门上的房间号，与目标教室代码对照。','Compare the room code beside or on the door with the destination code.')}</li></ol>${button('showIndoorClue','展开室内示意图','Show indoor sketch','outline full')}${button('atDoor','已看到对应门牌／标识','I can see the matching door sign')}`;
 if(stage===4)body=`<h3>${t('最后一条线索，由使用者确认。','The last clue needs a human check.')}</h3><div class="found-ticket"><span>${esc(n(b))} · ${esc(floor)}</span><strong>${esc(n(p))}</strong><small>${t('核对建筑、楼层和门口标识','MATCH BUILDING, FLOOR AND DOOR SIGN')}</small></div><p>${p.type==='toilet'?t('是否已找到对应厕所，并确认所需设施可以使用？','Have you found this toilet and confirmed the facilities needed are usable?'):t('是否已找到与课程信息一致的教室门口？系统不会仅凭位置自动判定完成。','Have you found the classroom door that matches the class information? Location alone does not mark the task complete.')}</p>${button('finishGuide','是的，找到了。结案。','Yes, found it. Case closed.')}${button('notFound','还没找到／无法使用','Not found / cannot use it','outline full')}${recovery?`<div class="recovery-panel" role="status"><strong>${t('线索暂未接上，目的地仍保留。','A missing clue. The destination stays saved in this trail.')}</strong><p>${t('先核对当前建筑与楼层。标识缺失或通道无法使用时，停止跟随示例路线，向现场服务台或工作人员询问。','Recheck the building and floor. If signs are missing or access is blocked, stop following the scenario route and ask an on-site service desk or staff member.')}</p>${button('retryIndoor','重新查看室内线索','Review indoor clues','text-button full')}${button('recheckFloor','重新核对楼层','Recheck the floor','text-button full')}${p.type==='toilet'?button('otherToilets','查看其他厕所线索','Explore other toilet clues','text-button full'):''}${button('leaveFeedback','记录缺失或不清楚的线索','Record a missing or unclear clue','text-button full')}</div>`:''}`;
 return `<div class="detail-toolbar"><span class="eyebrow">FOLLOWING A CLUE</span>${button('endGuide','结束','End','text-button')}</div>${facts}<ol class="journey-progress" aria-label="${t('找路进度','Wayfinding progress')}">${journeySteps.map((s,i)=>`<li class="${i===stage?'current':i<stage?'done':''}" ${i===stage?'aria-current="step"':''}><b>${i<stage?'✓':['◎','⌂','≋','↱','✓'][i]}</b><small class="step-number">0${i+1}</small><span>${s[en?1:0]}</span></li>`).join('')}</ol><div class="route-instruction journey-stage" data-stage="${stage}"><p class="eyebrow">CLUE ${stage+1} / 5</p>${body}${stage>0?button('previousClue','← 返回上一步','← Previous clue','text-button full'):''}</div>${note}`;
}
